from pathlib import Path
def patch(path,old,new):
 p=Path(path);t=p.read_text()
 if new in t: print("already applied:",path); return
 if old not in t: raise SystemExit("HF7 integration anchor not found: "+path)
 p.write_text(t.replace(old,new,1)); print("patched:",path)

