 if old not in t: raise SystemExit("HF7 serializer anchor 1 not found")
 t=t.replace(old,new,1)
 t=t.replace('if scene=="thank_you" and not thank_available:scene="live"\n','if scene=="thank_you" and not thank_available:scene="live"\n if scene=="halftime_slideshow" and not slideshow_available:scene="live"\n',1)
 old='return {"game_id":str(game.id),"scene":scene,"version":row.version if row else 0,"updated_at":row.updated_at if row else (game.intro_updated_at or game.advertisement_updated_at or game.thank_you_updated_at),"intro":{"enabled":bool(game.intro_enabled),"image_url":_versioned_asset_url(game.intro_image_url,game.intro_updated_at) if intro_available else None},"advertisement":{"enabled":bool(game.advertisement_enabled),"image_url":_versioned_asset_url(game.advertisement_image_url,game.advertisement_updated_at) if advertisement_available else None},"thank_you":{"enabled":bool(game.thank_you_enabled),"image_url":_versioned_asset_url(game.thank_you_image_url,game.thank_you_updated_at) if thank_available else None}}'
 new='return {"game_id":str(game.id),"scene":scene,"version":row.version if row else 0,"updated_at":row.updated_at if row else (game.intro_updated_at or game.advertisement_updated_at or game.thank_you_updated_at),"intro":{"enabled":bool(game.intro_enabled),"image_url":_versioned_asset_url(game.intro_image_url,game.intro_updated_at) if intro_available else None},"advertisement":{"enabled":bool(game.advertisement_enabled),"image_url":_versioned_asset_url(game.advertisement_image_url,game.advertisement_updated_at) if advertisement_available else None},"halftime_slideshow":{"enabled":bool(slideshow and slideshow.enabled),"interval_seconds":slideshow.interval_seconds if slideshow else 10,"slides":[{"id":str(s.id),"artwork_id":str(a.id),"name":a.name,"image_url":a.image_url,"position":s.position} for s,a in slide_pairs]},"thank_you":{"enabled":bool(game.thank_you_enabled),"image_url":_versioned_asset_url(game.thank_you_image_url,game.thank_you_updated_at) if thank_available else None}}'
